func setLongFlag(cfg *Config, name string) {
	switch name {
	case "help":
		cfg.helpFlag = true
	case "version":
		cfg.versionFlag = true
	case "verbose":
		cfg.verboseFlag = true
	case "clear":
		cfg.clearFlag = true
	case "fit-width":
		cfg.fitWidthFlag = true
	case "stretch":
		cfg.stretchFlag = true
	case "watch":
		cfg.watchFlag = true
	case "invert":
		cfg.invertFlag = true
	case "fg-only":
		cfg.fgOnlyFlag = true
	}
}

func setShortFlag(cfg *Config, ch byte) {
	switch ch {
	case 'h':
		cfg.helpFlag = true
	case 'v':
		cfg.verboseFlag = true
	case 'g':
		cfg.grid = "auto"
	case 'l':
		cfg.label = "on"
	}
}

// validateLong validates and sets long option value. optName is "--name" for error messages needing option name (e.g., int parsing).
// Returns (errMsg, hasError). If no error, sets cfg and returns ("", false).
func validateLong(cfg *Config, name, value, optDisplay string) (string, bool) {
	switch name {
	case "files":
		cfg.filesList = append(cfg.filesList, value)
		return "", false
	case "files0":
		cfg.files0List = append(cfg.files0List, value)
		return "", false
