package main

import (
	"os"
)

func checkGlyphFileMagic(path string) bool {
	fi, err := os.Stat(path)
	if err != nil {
		return false
	}
	if fi.IsDir() {
		return false
	}
	if fi.Size() == 0 {
		return false
	}
	if fi.Size() < 4 {
		return false
	}
	f, err := os.Open(path)
	if err != nil {
		return false
	}
	defer f.Close()
	buf := make([]byte, 4)
	n, err := f.Read(buf)
	if err != nil || n < 4 {
		return false
	}
	// TTF: 00 01 00 00
	if buf[0]==0x00 && buf[1]==0x01 && buf[2]==0x00 && buf[3]==0x00 {
		return true
	}
	// OTF: OTTO
	if buf[0]=='O' && buf[1]=='T' && buf[2]=='T' && buf[3]=='O' {
		return true
	}
	// true, typ1, ttcf
	if (buf[0]=='t' && buf[1]=='r' && buf[2]=='u' && buf[3]=='e') ||
		(buf[0]=='t' && buf[1]=='y' && buf[2]=='p' && buf[3]=='1') ||
		(buf[0]=='t' && buf[1]=='t' && buf[2]=='c' && buf[3]=='f') {
		return true
	}
	// WOFF: wOFF
	if buf[0]=='w' && buf[1]=='O' && buf[2]=='F' && buf[3]=='F' {
		return true
	}
	// PCF: Magic? PCF files start with 0x70636601? Actually "\x01\x66\x63\x70"? Let's just reject PCF for now? Or accept any file starting with 0x01? Safer to reject.
	return false
}

func isGlyphFileEmpty(path string) bool {
	fi, err := os.Stat(path)
	if err != nil {
		return false
	}
	if fi.IsDir() {
		return false
	}
	return fi.Size() == 0
}
