func maskShiftBits(mask uint32) (shift int, bits int) {
	if mask == 0 {
		return 0, 0
	}
	shift = 0
	for (mask & 1) == 0 {
		mask >>= 1
		shift++
	}
	bits = 0
	for (mask & 1) == 1 {
		mask >>= 1
		bits++
	}
	return shift, bits
}

