func parseSVGFill(s string) (color.RGBA, bool) {
	// Find fill="..." (first occurrence)
	lower := strings.ToLower(s)
	idx := strings.Index(lower, "fill")
	if idx == -1 {
		return color.RGBA{}, false
	}
	// Find "=" or ":" after? For style="fill:red" vs fill="red". Handle both.
	// Look ahead 10 chars for "=" or ":"
	sub := s[idx : min(len(s), idx+20)]
	eqIdx := strings.Index(sub, "=")
	colonIdx := strings.Index(sub, ":")
	sepIdx := -1
	if eqIdx != -1 && colonIdx != -1 {
		if eqIdx < colonIdx {
			sepIdx = idx + eqIdx
		} else {
			sepIdx = idx + colonIdx
		}
	} else if eqIdx != -1 {
		sepIdx = idx + eqIdx
	} else if colonIdx != -1 {
		sepIdx = idx + colonIdx
	} else {
		return color.RGBA{}, false
	}
	rest := s[sepIdx+1:]
	rest = strings.TrimLeft(rest, " \t\n\r\"'")
	// rest starts with color value until "\"", "'", ";", " ", ">", etc.
	end := len(rest)
	for i, ch := range rest {
		if ch == '"' || ch == '\'' || ch == ';' || ch == ' ' || ch == '>' || ch == '\t' || ch == '\n' || ch == '\r' {
			end = i
			break
		}
	}
	val := rest[:end]
	if val == "" || strings.ToLower(val) == "none" {
		return color.RGBA{}, false
	}
	// Parse color via parseColor (which handles hex + names)
	if col, ok := parseColor(val); ok {
		return color.RGBA{col[0], col[1], col[2], 255}, true
	}
	// Try rgb(r,g,b)? parseColor doesn't handle rgb(), but SVG may use it. Handle simple rgb(255,0,0)?
