		// Find closing ")"
		// val is truncated at " "? Actually rgb(255, 0, 0) contains spaces and commas, our truncation at space would cut. Need to handle differently: For rgb(), need to capture until ")".
		// Re-extract with ")" as terminator.
		rest2 := s[sepIdx+1:]
		rest2 = strings.TrimLeft(rest2, " \t\n\r\"'")
		end2 := strings.Index(rest2, ")")
		if end2 != -1 {
			rgbStr := rest2[:end2+1] // include ")"
			// Parse numbers inside
			inner := rgbStr[strings.Index(rgbStr, "(")+1 : strings.Index(rgbStr, ")")]
			parts := strings.Split(inner, ",")
			if len(parts) >= 3 {
				r := parseComponent(parts[0])
				g := parseComponent(parts[1])
				b := parseComponent(parts[2])
				return color.RGBA{uint8(r), uint8(g), uint8(b), 255}, true
			}
		}
		return color.RGBA{}, false
	}
	return color.RGBA{}, false
}

func parseComponent(s string) int {
	s = strings.TrimSpace(s)
	s = strings.Trim(s, "\"' \t")
	if strings.HasSuffix(s, "%") {
		s = strings.TrimSuffix(s, "%")
		if fv, err := parseFloat(s); err == nil {
			return int(fv * 255 / 100)
		}
		return 0
	}
	if iv, err := parseInt(s); err == nil {
		if iv < 0 {
			iv = 0
		}
		if iv > 255 {
			iv = 255
		}
		return iv
	}
	return 0
}

