		}
		// Handle previous disposal (for i>0): previous frame's disposal affects canvas before drawing current.
		if i > 0 {
			prevDisp := byte(0)
			if i-1 < len(g.Disposal) {
				prevDisp = g.Disposal[i-1]
			}
			prevBounds := g.Image[i-1].Bounds()
			if prevDisp == 2 {
				// Clear previous bounds to transparent (or bg?)
				// Use transparent black? Or bg color? For simplicity, clear to transparent.
				for y := prevBounds.Min.Y; y < prevBounds.Max.Y; y++ {
					for x := prevBounds.Min.X; x < prevBounds.Max.X; x++ {
						if x >= 0 && x < w && y >= 0 && y < h {
							canvas.SetRGBA(x, y, color.RGBA{0, 0, 0, 0})
						}
					}
				}
			} else if prevDisp == 3 {
				if prevCanvas != nil {
					copy(canvas.Pix, prevCanvas.Pix)
				}
			}
			// For disposal 0,1: keep canvas as is (do nothing)
		}
