		if disp == 3 {
			prevCanvas = saved
		} else {
			// For other disposals, prevCanvas not needed? But if next frame has disposal 3, it needs its own saved, not this. Good.
			// However, if current disposal !=3, prevCanvas should be nil? Actually disposal 3 of previous already handled above using prevCanvas from previous iteration. Good.
			// Keep prevCanvas for next? No, only needed if previous was 3. Good: After handling previous, clear? Actually prevCanvas should persist only for one iteration (for next frame's previous disposal). If current is not 3, next iteration's previous (current) is not 3, so prevCanvas not needed. Good: Set to nil? But what if we have consecutive 3s? Each saves its own. Good.
			// To be safe, keep as is? Actually if current is not 3, next's previous is not 3, so prevCanvas won't be used. Good: Leave as is (will be overwritten when needed).
		}
		// Draw current paletted image onto canvas (with transparency: palette index with transparent? Go's Paletted has Palette, but transparent index? GIF extension sets transparent? Go's DecodeAll handles transparency by setting palette entry to transparent? Actually g.Image[i].Palette includes transparent? The paletted image's transparent index is not stored, but pixels with transparent color have alpha 0? Go's gif package sets transparent pixels to palette index with transparent? Hmm. For simplicity, treat palette color with alpha 0 as transparent (skip).
		bounds := palImg.Bounds()
		for y := bounds.Min.Y; y < bounds.Max.Y; y++ {
			for x := bounds.Min.X; x < bounds.Max.X; x++ {
				c := palImg.At(x, y)
				// c is color from palette (could be transparent)
				_, _, _, a := c.RGBA()
				if a == 0 {
					continue // transparent, keep canvas
				}
				r, g, b, aa := c.RGBA()
				if x >= 0 && x < w && y >= 0 && y < h {
					canvas.SetRGBA(x, y, color.RGBA{uint8(r >> 8), uint8(g >> 8), uint8(b >> 8), uint8(aa >> 8)})
				}
			}
		}
		// Copy canvas as frame
		frameCopy := image.NewRGBA(canvas.Bounds())
		copy(frameCopy.Pix, canvas.Pix)
		frames = append(frames, frameCopy)
	}
	return frames
}

// QOI decoder (minimal, from spec knowledge)
func decodeQOI(data []byte) (image.Image, error) {
	if len(data) < 14+8 {
		return nil, fmt.Errorf("too short")
	}
	if string(data[0:4]) != "qoif" {
		return nil, fmt.Errorf("bad magic")
	}
	w := binary.BigEndian.Uint32(data[4:8])
	h := binary.BigEndian.Uint32(data[8:12])
	channels := data[12]
	// colorspace := data[13] (ignore)
	if w == 0 || h == 0 || w > 10000 || h > 10000 {
		return nil, fmt.Errorf("bad dims")
	}
	if channels != 3 && channels != 4 {
		return nil, fmt.Errorf("bad channels")
	}
	// Check end marker: last 8 bytes should be 00 00 00 00 00 00 00 01
	if len(data) < 14+8 {
		return nil, fmt.Errorf("too short")
	}
	end := data[len(data)-8:]
	expected := []byte{0, 0, 0, 0, 0, 0, 0, 1}
	for i := range expected {
		if end[i] != expected[i] {
			return nil, fmt.Errorf("bad end")
		}
	}
	payload := data[14 : len(data)-8]
	img := image.NewRGBA(image.Rect(0, 0, int(w), int(h)))
	// QOI state
	var index [64][4]uint8
	var r, g, b, a uint8 = 0, 0, 0, 255
	pxLen := int(w) * int(h)
	pxPos := 0
	p := 0
	hash := func(r, g, b, a uint8) int {
		return int((uint32(r)*3 + uint32(g)*5 + uint32(b)*7 + uint32(a)*11) % 64)
	}
	putPixel := func(r, g, b, a uint8) {
		if pxPos >= pxLen {
			return
		}
		x := pxPos % int(w)
		y := pxPos / int(w)
		img.SetRGBA(x, y, color.RGBA{r, g, b, a})
		index[hash(r, g, b, a)] = [4]uint8{r, g, b, a}
		pxPos++
	}
	for pxPos < pxLen {
		if p >= len(payload) {
			return nil, fmt.Errorf("truncated")
		}
		b1 := payload[p]
		p++
		if b1 == 0xFE { // QOI_OP_RGB
			if p+2 >= len(payload)+1 { // need 3 bytes
				if p+2 > len(payload) {
					return nil, fmt.Errorf("truncated rgb")
				}
			}
			if p+2 >= len(payload)+1 {
				return nil, fmt.Errorf("truncated")
			}
			if p+2 > len(payload)-1 && p+2 != len(payload) {
				// check bounds
			}
			if p+2 > len(payload) {
				return nil, fmt.Errorf("truncated")
			}
			// Actually need 3 bytes: payload[p], [p+1], [p+2]? No, we already consumed b1, need 3 more: r,g,b
			if p+2 >= len(payload) {
				// Need p, p+1, p+2? Wait p is index of next byte after b1. Need 3 bytes: p, p+1, p+2? No, p points to next, need p, p+1, p+2? Actually need 3 bytes total: r,g,b. So need p+2 < len.
				if p+2 >= len(payload) && !(p+2 == len(payload)) {
					// Allow?
				}
			}
			if p+2 >= len(payload) {
				// Check: if p == len-2? Need 3 bytes, but only 2 left => truncated
				// For safety, check p+2 < len? Actually need p <= len-3? Let's just check.
				if p+2 > len(payload)-1 {
					return nil, fmt.Errorf("truncated rgb")
				}
			}
			r = payload[p]
			g = payload[p+1]
			b = payload[p+2]
			p += 3
			putPixel(r, g, b, a)
		} else if b1 == 0xFF { // QOI_OP_RGBA
			if p+3 > len(payload) {
				return nil, fmt.Errorf("truncated rgba")
			}
			r = payload[p]
			g = payload[p+1]
			b = payload[p+2]
			a = payload[p+3]
			p += 4
			putPixel(r, g, b, a)
		} else if (b1 & 0xC0) == 0x00 { // QOI_OP_INDEX
			idx := int(b1 & 0x3F)
			r = index[idx][0]
			g = index[idx][1]
			b = index[idx][2]
			a = index[idx][3]
			putPixel(r, g, b, a)
		} else if (b1 & 0xC0) == 0x40 { // QOI_OP_DIFF
			dr := int((b1>>4)&0x03) - 2
			dg := int((b1>>2)&0x03) - 2
			db := int(b1&0x03) - 2
			r = uint8(int(r) + dr)
			g = uint8(int(g) + dg)
			b = uint8(int(b) + db)
			putPixel(r, g, b, a)
		} else if (b1 & 0xC0) == 0x80 { // QOI_OP_LUMA
			if p >= len(payload) {
				return nil, fmt.Errorf("truncated luma")
			}
			b2 := payload[p]
			p++
			dg := int(b1&0x3F) - 32
			dr_dg := int((b2>>4)&0x0F) - 8
			db_dg := int(b2&0x0F) - 8
			dr := dr_dg + dg
			db := db_dg + dg
			r = uint8(int(r) + dr)
			g = uint8(int(g) + dg)
			b = uint8(int(b) + db)
			putPixel(r, g, b, a)
		} else if (b1 & 0xC0) == 0xC0 { // QOI_OP_RUN
			run := int(b1&0x3F)
			for i := 0; i <= run; i++ {
				putPixel(r, g, b, a)
				if pxPos >= pxLen {
					break
				}
			}
		}
	}
	return img, nil
}

func decodeTIFFMinimal(data []byte) (image.Image, error) {
	// Minimal TIFF decoder for test pixel.tiff (1x1, uncompressed RGB?).
	// TIFF structure: Header (8 bytes): byte order (II/MM), magic 42, offset to first IFD.
	// IFD: 2 bytes count, then 12 bytes per entry (tag, type, count, value/offset), then 4 bytes next IFD offset.
	// Tags needed: ImageWidth (256), ImageLength (257), BitsPerSample (258), Compression (259, must be 1 uncompressed), PhotometricInterpretation (262), StripOffsets (273), SamplesPerPixel (277), RowsPerStrip (278), StripByteCounts (279), etc.
	// For simplicity, support only uncompressed (1), RGB (2) or BlackIsZero (1) or WhiteIsZero (0)?, 8 bits per sample, 1 or 3 samples.
	// This is enough for test file (likely 1x1 RGB uncompressed).
	if len(data) < 8 {
		return nil, fmt.Errorf("too short")
	}
	var order binary.ByteOrder
	if data[0]=='I' && data[1]=='I' {
		order = binary.LittleEndian
	} else if data[0]=='M' && data[1]=='M' {
		order = binary.BigEndian
	} else {
		return nil, fmt.Errorf("bad order")
	}
	magic := order.Uint16(data[2:4])
	if magic != 42 {
		return nil, fmt.Errorf("bad magic")
	}
	ifdOffset := order.Uint32(data[4:8])
	if int(ifdOffset)+2 > len(data) {
		return nil, fmt.Errorf("bad ifd offset")
	}
	numEntries := int(order.Uint16(data[ifdOffset : ifdOffset+2]))
	// Parse entries
	var width, height uint32
	var bitsPerSample []uint16
	var compression uint16 = 1
	var photometric uint16
	var stripOffsets []uint32
	var samplesPerPixel uint16 = 1
	var rowsPerStrip uint32 = 0xFFFFFFFF
	var stripByteCounts []uint32
	// Helper to read value (for types SHORT/LONG with count 1, value stored in entry itself)
	for i := 0; i < numEntries; i++ {
		off := int(ifdOffset) + 2 + i*12
		if off+12 > len(data) {
			return nil, fmt.Errorf("bad entry")
		}
		tag := order.Uint16(data[off : off+2])
		typ := order.Uint16(data[off+2 : off+4])
		count := order.Uint32(data[off+4 : off+8])
		valBytes := data[off+8 : off+12]
		readU16 := func() []uint16 {
			if typ == 3 { // SHORT
				if count == 1 {
					return []uint16{order.Uint16(valBytes[0:2])}
				} else if count == 2 {
					return []uint16{order.Uint16(valBytes[0:2]), order.Uint16(valBytes[2:4])}
				} else {
					// Offset
					voff := order.Uint32(valBytes)
					if int(voff)+int(count)*2 > len(data) {
						return nil
					}
					res := make([]uint16, count)
					for j := uint32(0); j < count; j++ {
						res[j] = order.Uint16(data[int(voff)+int(j)*2:])
					}
					return res
				}
			}
			return nil
		}
		readU32 := func() []uint32 {
			if typ == 4 { // LONG
				if count == 1 {
					return []uint32{order.Uint32(valBytes)}
				} else {
					voff := order.Uint32(valBytes)
					if int(voff)+int(count)*4 > len(data) {
						return nil
					}
					res := make([]uint32, count)
					for j := uint32(0); j < count; j++ {
						res[j] = order.Uint32(data[int(voff)+int(j)*4:])
					}
					return res
				}
			} else if typ == 3 { // SHORT with LONG expected? For strip offsets/counts, type could be SHORT or LONG. Handle SHORT as well.
				vals16 := readU16()
				if vals16 == nil {
					return nil
				}
				res := make([]uint32, len(vals16))
				for j, v := range vals16 {
					res[j] = uint32(v)
				}
				return res
			}
			return nil
		}
		switch tag {
		case 256:
			vals := readU32()
			if vals == nil || len(vals) < 1 {
				// Try SHORT?
				if typ == 3 {
					v16 := readU16()
					if v16 != nil && len(v16) > 0 {
						width = uint32(v16[0])
						continue
					}
				}
				return nil, fmt.Errorf("bad width")
			}
			width = vals[0]
		case 257:
			vals := readU32()
			if vals == nil || len(vals) < 1 {
				if typ == 3 {
					v16 := readU16()
					if v16 != nil && len(v16) > 0 {
						height = uint32(v16[0])
						continue
					}
				}
				return nil, fmt.Errorf("bad height")
			}
			height = vals[0]
		case 258:
			vals := readU16()
			if vals == nil {
				return nil, fmt.Errorf("bad bps")
			}
			bitsPerSample = vals
		case 259:
			vals := readU16()
			if vals == nil || len(vals) < 1 {
				return nil, fmt.Errorf("bad comp")
			}
			compression = vals[0]
		case 262:
			vals := readU16()
			if vals == nil || len(vals) < 1 {
				return nil, fmt.Errorf("bad photo")
			}
			photometric = vals[0]
		case 273:
			vals := readU32()
			if vals == nil {
				return nil, fmt.Errorf("bad strip offsets")
			}
			stripOffsets = vals
		case 277:
			vals := readU16()
			if vals == nil || len(vals) < 1 {
				return nil, fmt.Errorf("bad spp")
			}
			samplesPerPixel = vals[0]
		case 278:
			vals := readU32()
			if vals == nil || len(vals) < 1 {
				if typ == 3 {
					v16 := readU16()
					if v16 != nil && len(v16) > 0 {
						rowsPerStrip = uint32(v16[0])
						continue
					}
				}
				return nil, fmt.Errorf("bad rps")
			}
			rowsPerStrip = vals[0]
		case 279:
			vals := readU32()
			if vals == nil {
				return nil, fmt.Errorf("bad sbc")
			}
			stripByteCounts = vals
		}
	}
	if width == 0 || height == 0 || width > 10000 || height > 10000 {
		return nil, fmt.Errorf("bad dims")
	}
	if compression != 1 {
		return nil, fmt.Errorf("unsupported compression")
	}
	if len(bitsPerSample) == 0 {
		bitsPerSample = []uint16{8}
	}
	// Check bits: must be 8 for all?
	for _, b := range bitsPerSample {
		if b != 8 {
			return nil, fmt.Errorf("unsupported bits")
		}
	}
	if samplesPerPixel != 1 && samplesPerPixel != 3 && samplesPerPixel != 4 {
		return nil, fmt.Errorf("unsupported spp")
	}
	if len(stripOffsets) == 0 || len(stripByteCounts) == 0 {
		return nil, fmt.Errorf("no strips")
	}
	img := image.NewRGBA(image.Rect(0, 0, int(width), int(height)))
	// Read strips
	// For simplicity, assume RowsPerStrip covers all rows in one strip? Or multiple strips. Handle multiple.
	y := 0
	for si := 0; si < len(stripOffsets); si++ {
		off := stripOffsets[si]
		// count := stripByteCounts[si] (ignore, use rows)
		rowsInStrip := rowsPerStrip
		if uint32(y)+rowsInStrip > height {
			rowsInStrip = height - uint32(y)
		}
		expectedBytes := int(rowsInStrip) * int(width) * int(samplesPerPixel)
		if int(off)+expectedBytes > len(data) {
			return nil, fmt.Errorf("strip out of bounds")
		}
		stripData := data[off : int(off)+expectedBytes]
		idx := 0
		for row := 0; row < int(rowsInStrip); row++ {
			for col := 0; col < int(width); col++ {
				var r, g, b, a uint8 = 0, 0, 0, 255
				if samplesPerPixel == 1 {
					v := stripData[idx]
					idx++
					if photometric == 0 { // WhiteIsZero? 0=WhiteIsZero, 1=BlackIsZero
						v = 255 - v
					}
					r, g, b = v, v, v
				} else if samplesPerPixel == 3 {
					r = stripData[idx]
					g = stripData[idx+1]
					b = stripData[idx+2]
					idx += 3
				} else if samplesPerPixel == 4 {
					r = stripData[idx]
					g = stripData[idx+1]
					b = stripData[idx+2]
					a = stripData[idx+3]
					idx += 4
				}
				img.SetRGBA(col, y+row, color.RGBA{r, g, b, a})
			}
		}
		y += int(rowsInStrip)
		if y >= int(height) {
			break
		}
	}
	_ = photometric
	return img, nil
}

