func parseWebPDimensions(data []byte) (int, int, bool) {
	// Search for VP8X, VP8 , VP8L
	// RIFF header: 0-3 "RIFF", 4-7 file size, 8-11 "WEBP"
	if len(data) < 12 {
		return 0, 0, false
	}
	pos := 12
	for pos+8 <= len(data) {
		tag := string(data[pos : pos+4])
		size := binary.LittleEndian.Uint32(data[pos+4 : pos+8])
		chunkDataStart := pos + 8
		chunkDataEnd := chunkDataStart + int(size)
		if chunkDataEnd > len(data) {
			// Truncated, but try anyway
			chunkDataEnd = len(data)
		}
		if tag == "VP8 " {
			// Lossy: Need at least 10 bytes in chunk
			if chunkDataEnd-chunkDataStart < 10 {
				return 0, 0, false
			}
			// Frame tag (3 bytes), then 3 bytes start code (9D 01 2A), then width/height (2 bytes each, little endian, 14 bits)
			// Actually VP8 frame header: Byte 0-2: frame tag, Byte 3-5: start code (0x9D 0x01 0x2A), Byte 6-7: width (14 bits, scale), Byte 8-9: height.
			cd := data[chunkDataStart:chunkDataEnd]
			if len(cd) < 10 {
				return 0, 0, false
			}
			// Check start code?
			// if cd[3]!=0x9D || cd[4]!=0x01 || cd[5]!=0x2A { return ... } // May fail for some? Skip check.
			w := int(binary.LittleEndian.Uint16(cd[6:8])) & 0x3FFF
			h := int(binary.LittleEndian.Uint16(cd[8:10])) & 0x3FFF
			return w, h, true
		} else if tag == "VP8L" {
			// Lossless: 1 byte signature (0x2F), then 4 bytes: width (14 bits) + height (14 bits) + alpha (1 bit) + version (3 bits)
			if chunkDataEnd-chunkDataStart < 5 {
				return 0, 0, false
			}
			cd := data[chunkDataStart:chunkDataEnd]
			if cd[0] != 0x2F {
				return 0, 0, false
			}
			b0 := uint32(cd[1])
			b1 := uint32(cd[2])
			b2 := uint32(cd[3])
			b3 := uint32(cd[4])
			w := int(((b1&0x3F)<<8 | b0) + 1)
			h := int(((b3&0x0F)<<10 | (b2<<2) | ((b1>>6)&0x03)) + 1)
			_ = b0
			_ = b1
			_ = b2
			_ = b3
