func medianU8(vals []uint8) uint8 {
	if len(vals) == 0 {
		return 0
	}
	// Copy and sort
	cp := make([]uint8, len(vals))
	copy(cp, vals)
	for i := 0; i < len(cp); i++ {
		for j := i + 1; j < len(cp); j++ {
			if cp[j] < cp[i] {
				cp[i], cp[j] = cp[j], cp[i]
			}
		}
	}
	return cp[len(cp)/2]
}

