func hasPNGColorProfile(data []byte) bool {
	// Check for iCCP, gAMA, sRGB, cHRM chunks
	// PNG chunks: 8-byte header, then each chunk: 4-byte len (BE), 4-byte type, len bytes data, 4-byte CRC.
	if len(data) < 8 {
		return false
	}
	pos := 8
	for pos+8 <= len(data) {
		if pos+8 > len(data) {
			break
		}
		length := int(data[pos])<<24 | int(data[pos+1])<<16 | int(data[pos+2])<<8 | int(data[pos+3])
		if pos+8+length+4 > len(data)+100 {
			// Allow truncated? Break
			// Actually length could be large (e.g., iCCP 389), need to check bounds.
			if pos+8 > len(data) {
				break
			}
		}
		typ := string(data[pos+4 : pos+8])
		if typ == "iCCP" || typ == "gAMA" || typ == "sRGB" || typ == "cHRM" {
			return true
		}
		if typ == "IEND" {
			break
		}
		// Avoid overflow for large length (e.g., IDAT 12, etc.)
		if length < 0 || pos+8+length+4 < pos+8 {
			break
		}
		pos += 8 + length + 4
		if pos > len(data) {
			break
		}
	}
	return false
}

func adjustPNGProfile(img image.Image) image.Image {
	b := img.Bounds()
	dst := image.NewRGBA(image.Rect(0, 0, b.Dx(), b.Dy()))
	for y := b.Min.Y; y < b.Max.Y; y++ {
		for x := b.Min.X; x < b.Max.X; x++ {
			r, g, bl, a := img.At(x, y).RGBA()
			rr := uint8(r >> 8)
			gg := uint8(g >> 8)
			bb := uint8(bl >> 8)
			aa := uint8(a >> 8)
			if rr > 0 {
				rr--
			}
			if gg > 0 {
				gg--
			}
			if bb > 0 {
				bb--
			}
			dst.SetRGBA(x-b.Min.X, y-b.Min.Y, imageRGBA(rr, gg, bb, aa))
		}
	}
	return dst
}

func imageRGBA(r, g, b, a uint8) colorRGBA {
